import numpy as np
from collections import deque
g=np.array([[0,9,3,3,1,5],[7,5,3,3,1,7],[3,3,3,3,9,2],[2,4,0,7,3,3],[4,3,5,3,3,3],[3,3,3,3,3,3]])
H,W=g.shape
outside=np.zeros_like(g,bool)
q=deque()
for i in range(H):
    for j in [0,W-1]:
        if g[i,j]!=3 and not outside[i,j]: outside[i,j]=True;q.append((i,j))
for j in range(W):
    for i in [0,H-1]:
        if g[i,j]!=3 and not outside[i,j]: outside[i,j]=True;q.append((i,j))
while q:
    i,j=q.popleft()
    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
        a,b=i+di,j+dj
        if 0<=a<H and 0<=b<W and g[a,b]!=3 and not outside[a,b]:
            outside[a,b]=True;q.append((a,b))
print("enclosed non-3 cells:")
for i in range(H):
    for j in range(W):
        if g[i,j]!=3 and not outside[i,j]:
            print(i,j,g[i,j])

r180=g[::-1,::-1]
tr=g.T
